import React from 'react'
import { connect } from 'react-redux'
import { Modal, Form, Button, Alert, Row, Col, Select, Icon, Input } from 'antd'
import ReconActions from '../../redux/recon/actions'
import Operator from './operator'
import { validateAddRuleValues } from '../../../helpers/validator'

const { resetReduxStateRecon, addFrequencyTrigger } = ReconActions

const FormItem = Form.Item
const Option = Select.Option
let id = 1
class AddRule extends React.Component {
  state = {
    regex: '',
    invalidMessage: '',
    selectorValues: '',
    selectionOperator: ''
  }
  async validateForm () {
    const { selectionOperator } = this.state
    return new Promise((resolve) => {
      let checkFields = selectionOperator === 'inlot' || selectionOperator === 'ninlot' ? ['names', 'keys', 'var', 'op'] : ['val', 'var', 'op']
      this.props.form.validateFields(checkFields, (error) => {
        resolve(!error)
      })
    })
  }

  onSubmit = async e => {
    e.preventDefault()

    const valid = await this.validateForm()
    if (!valid) {
      this.setState({ submitting: false })
      return
    }
    let data = this.props.form.getFieldsValue()
    let values = []
    data.names.map((name) => {
      values = [...values, [name]]
      return values
    })
    setTimeout(() => {
      this.setState({ submitting: false })

      data.op === 'inlot' || data.op === 'ninlot'
        ? this.props.addRule({ op: data.op, var: data.var.replace(/, /g, ','), val: values })
        : this.props.addRule({ op: data.op, var: data.var.replace(/, /g, ','), val: data.val })

      this.props.form.resetFields()
    }, 1000)
  }
  handleCancel = () => {
    this.props.onCloseModal()
  }
  onChangeSelector = (value) => {
    this.setState({ selectorValues: value.target.value })
  }
  remove = k => {
    const { form } = this.props
    // can use data-binding to get
    const keys = form.getFieldValue('keys')
    // We need at least one passenger
    if (keys.length === 1) {
      return
    }

    // can use data-binding to set
    form.setFieldsValue({
      keys: keys.filter(key => key !== k)
    })
  };
  add = () => {
    const { form } = this.props
    // can use data-binding to get
    const keys = form.getFieldValue('keys')
    const nextKeys = keys.concat(id++)
    // can use data-binding to set
    // important! notify form to detect changes
    form.setFieldsValue({
      keys: nextKeys
    })
  };
  validateName = (rule, value, callback) => {
    if ((/^([a-zA-Z ']){2,100}$/.test(value))) {
      callback()
    } else if ((/^([a-zA-Z ']){0,1}$/.test(value)) || (/^([a-zA-Z ']){101,1000}$/.test(value))) {
      callback('Character length should be 2-100') // eslint-disable-line
    } else {
      callback('Should be alphabet and or space') // eslint-disable-line
    }
  }
  checkValue = (rule, value, callback) => {
    const regex = new RegExp(rule.regex, 'g')
    if (regex.test(value)) {
      callback()
      return
    }
    callback(this.state.invalidMessage)
  }
  onChangeOperator = val => {
    const selectedOperator = Operator.filter(value => value.op === val)
    this.setState({
      selectionOperator: val,
      regex: selectedOperator[0].regex,
      invalidMessage: selectedOperator[0].invalidMessage
    })
  }
  render () {
    const { isOpen, form } = this.props
    const { selectorValues, selectionOperator } = this.state
    const { getFieldDecorator, getFieldValue } = form

    getFieldDecorator('keys', { initialValue: [0] })
    const keys = getFieldValue('keys')
    const formItems = keys.map((k) => (
      <Form.Item
        required={false}
        key={k}
      >
        {getFieldDecorator(`names[${k}]`, {
          // validateTrigger: ['onChange', 'onBlur'],
          rules: [
            {
              required: true
            },
            {
              validator: (rule, value, callback) => validateAddRuleValues(rule, value, callback, selectorValues)
            }
          ]
        })(<Select mode='tags' style={{ width: '95%' }} tokenSeparators={[',']} />)}
        {keys.length > 1 ? (
          <Icon
            className='dynamic-delete-button'
            type='minus-circle-o'
            onClick={() => this.remove(k)}
          />
        ) : null}
      </Form.Item>
    ))
    return (
      <Modal
        title='Add rule'
        visible={isOpen}
        footer={[]}
        closable={false}
        maskClosable={false}
        onCancel={this.handleCancel}
      >
        {
          alert.error !== undefined && (
            <Row style={{ marginBottom: '10px' }}>
              <Col>
                <Alert
                  message={alert.error}
                  type='error'
                  closable
                  onClose={this.onCloseAlert}
                />
              </Col>
            </Row>
          )
        }
        <Form onSubmit={this.onSubmit}>
          <label className='custom-label'>Selector</label>
          <FormItem style={{ fontSize: '11px' }}>
            {getFieldDecorator('var', {
              rules: [
                { required: true, message: 'Selector can not be empty' }
              ]
            })(
              // <Select mode="tags" style={{ width: '100%' }} onChange={(value) => this.onChangeSelector(value)} tokenSeparators={[',']} />
              <Input size='default' className='input-box' maxLength={128} onChange={(value) => this.onChangeSelector(value)} />
            )}
          </FormItem>
          <label className='custom-label'>Operator</label>
          <FormItem style={{ fontSize: '11px' }}>
            {getFieldDecorator('op', {
              rules: [
                { required: true, message: 'Operator can not be empty' }
              ]
            })(
              <Select
                showSearch
                placeholder='Select ...'
                style={{ width: '100%' }}
                filterOption={(input, option) => option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
                onChange={this.onChangeOperator}
              >
                {Operator.map((value, index) => <Option key={index} value={value.op}>{value.op}</Option>)}
              </Select>
            )}
          </FormItem>
          <label className='custom-label' style={{ marginRight: 4 }}>Value</label>
          {
            selectionOperator === 'inlot' || selectionOperator === 'ninlot'
              ? <Icon type='plus-circle' style={{ fontSize: 16, color: '#1890ff' }} onClick={() => this.add()} />
              : null
          }
          {
            selectionOperator === 'inlot' || selectionOperator === 'ninlot'
              ? formItems
              : <FormItem style={{ fontSize: '11px' }}>
                {getFieldDecorator('val', {
                  rules: [
                    { required: true, message: 'Value can not be empty' },
                    { validator: this.checkValue, regex: this.state.regex }
                  ]
                })(
                  <Input size='default' className='input-box' maxLength={128} />
                )}
              </FormItem>
          }

          <div style={{ textAlign: 'right' }}>
            <Button key='back' onClick={this.handleCancel}>Cancel</Button>
            <Button
              key='submit'
              type='primary'
              htmlType='submit'
              // loading={this.state.submitting}

              style={{ marginLeft: '10px' }}
            >
              Ok
            </Button>
          </div>
        </Form>
      </Modal>
    )
  }
}

const WrappedForm = Form.create({})(AddRule)

export default connect(
  state => ({
    Recon: state.Recon,
    Policy: state.Insurance
  }),
  { resetReduxStateRecon, addFrequencyTrigger }
)(WrappedForm)
